# Content verification (AGENTS.md lesson: verify the OUTPUT notebook)
import nbformat
nbformat.read(out_path, as_version=4)
text = open(out_path).read()
for token in ["SMOKE_N_PERM = 10", "n_perm_initial=SMOKE_N_PERM",
              "10x_human_lymph_node_A1_seed42_embeddings.npy",
              "10x_human_lymph_node_A1_seed42_labels.npy",
              "generate_dummy_external_data", "sldsc_lookup_plus=None",
              "adata_RNA_A1_dummyannot.h5ad", "runs/smoke-hello-pipeline",
              "SMOKE TEST COMPLETE", "run_single_lymph_node_section",
              "TRAIT_PANELS_LYMPH_NODE", "engine3b_surface_proteome_gwas"]:
    assert token in text, f"MISSING TOKEN: {token}"
assert text.count("e3_z, n_perm_initial=SMOKE_N_PERM") == 2, "driver perm edit must appear at exactly the 2 triangulation call sites"
for bad in ["\u201c", "\u201d", "\u2018", "\u2019"]:
    assert bad not in text, f"curly-quote character leaked into notebook: {bad}"
print("content check: all key tokens present, perm edit x2, no curly quotes")
